// Parse incoming WhatsApp Cloud API webhook
const body = $input.first().json.body || {};
const entry = body.entry?.[0];
const value = entry?.changes?.[0]?.value;
const messages = value?.messages;

// Ignore delivery/read status updates
if (!messages || !messages[0]) return [];

const msg = messages[0];

// Only process text messages
if (msg.type !== 'text') return [];

const from = msg.from;
const rawText = (msg.text?.body || '').trim();
const phoneNumberId = value?.metadata?.phone_number_id || '793508627177133';

// Password check: message must start with '6778'
const PASSWORD = '6778';
let authenticated = false;
let question = '';

if (rawText === PASSWORD) {
  // Boss just typed the password alone — send help menu
  authenticated = true;
  question = '__HELP__';
} else if (rawText.startsWith(PASSWORD + ' ')) {
  // Password + space + question
  authenticated = true;
  question = rawText.slice(PASSWORD.length + 1).trim();
} else {
  // Wrong or no password
  authenticated = false;
  question = rawText;
}

return [{ json: {
  from,
  messageId: msg.id,
  rawText,
  question,
  authenticated,
  phoneNumberId
}}];

// Build Gemini API request for SQL generation
const question = $('Extract Message').first().json.question;
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Hong_Kong' });

const systemPrompt = `You are a SQL expert for GO24 Fitness gym chain in Hong Kong. Generate ONE PostgreSQL SELECT query to answer the manager's question. Return ONLY the raw SQL — no explanation, no markdown, no code blocks.

Today (HKT): ${today}

Database schema:

pgm.members (member_code, name, phone, email, gender, dob DATE, join_date DATE, plan_type, plan_start DATE, plan_end DATE, status VARCHAR, pt_sessions_left INT, last_visit DATE, total_paid NUMERIC, branch, notes, updated_at TIMESTAMP)
status values: 'Active', 'Frozen', 'Expired', 'Cancelled'
branch: club names e.g. 'GO24 MK', 'GO24 CWB', 'GO24 TKO'

commissions.sold (club, sell_date DATE, user_number, first_name, product_name, package_name, sold_quantity, net_sold NUMERIC, gross_sold NUMERIC, is_paid BOOL, is_new BOOL, sold_employee, discount NUMERIC, expiry_date DATE, commission_category)

commissions.done (club, done_date DATE, sell_date DATE, user_number, product_name, done_quantity NUMERIC, net_sold NUMERIC, done_amount NUMERIC, done_gross NUMERIC, done_employee, done_employee_position, department, commission_category)

studio.classes (club, class_name, category, employee_name, start_date DATE, day_of_week, class_time, duration INT, users_limit INT, users_assigned INT, users_present INT, rating NUMERIC)

studio.by_member (club, class_date DATE, class_name, first_name, last_name, user_number, has_presence BOOL)

pos.transactions (club, transaction_date DATE, product_name, category, quantity NUMERIC, net_amount NUMERIC, gross_amount NUMERIC, payment_method, full_name, employee)

payments.epayment_log (club, user_number, name, payment_date DATE, amount NUMERIC, net_amount NUMERIC, status, provider, membership_status, payment_plan, transaction_type)

Rules:
- Always LIMIT 20 for detail queries; no limit for aggregations
- For member name lookup: use ILIKE '%name%'
- Use readable English column aliases`;

return [{ json: {
  geminiBody: JSON.stringify({
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: question }] }],
    generationConfig: { maxOutputTokens: 600, temperature: 0.1 }
  }),
  question
}}];

const response = $input.first().json;
let sql = response.candidates?.[0]?.content?.parts?.[0]?.text || '';
sql = sql.replace(/```sql/gi, '').replace(/```/g, '').trim();
if (!sql.toUpperCase().startsWith('SELECT')) {
  throw new Error('Gemini returned non-SELECT: ' + sql.substring(0, 150));
}
const question = $('Build SQL Request').first().json.question;
return [{ json: { sql, question } }];

const results = $input.all().map(i => i.json);
const question = $('Extract SQL').first().json.question;
const resultSummary = results.length === 0 ? 'No results found' : JSON.stringify(results, null, 2);
const systemPrompt = 'You are a helpful assistant for GO24 Fitness gym management in Hong Kong. The manager asked a question and you have database results. Write a concise, friendly reply in the same language as the question (Cantonese/Traditional Chinese or English). Be brief (1–4 sentences). Present numbers clearly. Add 1–2 relevant emoji. Do NOT mention SQL or database.';
const userContent = `Manager asked: ${question}\n\nDatabase result (${results.length} rows):\n${resultSummary}`;
return [{ json: {
  geminiBody: JSON.stringify({
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: userContent }] }],
    generationConfig: { maxOutputTokens: 400, temperature: 0.7 }
  }),
  rowCount: results.length
}}];

const response = $input.first().json;
const answer = response.candidates?.[0]?.content?.parts?.[0]?.text || '唔好意思，暫時無法回答。';
const to = $('Extract Message').first().json.from;
return [{ json: { answer, to } }];
